import{_ as t,o as a,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"Test MC_09 - VIO (Visual-Inertial Odometry)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test_cards/mc_09_vio.md","filePath":"zh/test_cards/mc_09_vio.md"}'),r={name:"zh/test_cards/mc_09_vio.md"};function l(s,e,n,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="test-mc-09-vio-visual-inertial-odometry" tabindex="-1">Test MC_09 - VIO (Visual-Inertial Odometry) <a class="header-anchor" href="#test-mc-09-vio-visual-inertial-odometry" aria-label="Permalink to &quot;Test MC_09 - VIO (Visual-Inertial Odometry)&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that external vision (VIO) works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using VIO for navigation</p><p>Ensure that the drone can go into <a href="./../flight_modes_mc/altitude">Altitude</a> / <a href="./../flight_modes_mc/position">Position</a> mode while still on the ground</p><p>Ensure there are no other sources of positioning besides VIO:</p><ul><li><a href="./../advanced_config/parameter_reference#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>15</code></li><li><a href="./../advanced_config/parameter_reference#SYS_HAS_MAG">SYS_HAS_MAG</a>: <code>0</code></li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/altitude">Altitude mode</a></p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ <a href="./../flight_modes_mc/position">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="降落" tabindex="-1">降落 <a class="header-anchor" href="#降落" aria-label="Permalink to &quot;降落&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="预期成果" tabindex="-1">预期成果 <a class="header-anchor" href="#预期成果" aria-label="Permalink to &quot;预期成果&quot;">​</a></h2><ul><li>当油门升高时，起飞应该是平稳的</li><li>Drone should hold altitude in Altitude mode without wandering</li><li>Drone should hold position within 1 meter in Position mode without pilot moving sticks</li><li>在上述任何飞行模式中都不应出现振荡</li><li>着陆时，直升机不应在地面上反弹</li></ul>',23)])])}const u=t(r,[["render",l]]);export{p as __pageData,u as default};
